import test from 'node:test';import assert from 'node:assert/strict';import {createServer} from 'node:http';import {readFile} from 'node:fs/promises';import {resolve,extname} from 'node:path';import {spawn} from 'node:child_process';import {fixture} from './fixture.mjs';
const root=resolve('.'),mime={'.html':'text/html','.mjs':'text/javascript','.json':'application/json'};
async function browserCheck({path='/',script}){
 const data=fixture();const server=createServer(async(req,res)=>{try{const pathname=new URL(req.url,'http://127.0.0.1').pathname;if(pathname==='/website-data.json'){res.setHeader('content-type','application/json');res.end(JSON.stringify(data));return;}if(pathname==='/browser-check.mjs'){res.setHeader('content-type','text/javascript');res.end("const run=async()=>{for(let n=0;n<200&&document.body.dataset.state==='loading';n++)await new Promise(r=>setTimeout(r,25));try{"+script+";const p=document.createElement('pre');p.id='browser-result';p.textContent='BROWSER_PASS';document.body.append(p);}catch(e){const p=document.createElement('pre');p.id='browser-result';p.textContent='BROWSER_FAIL:'+e.message;document.body.append(p);}};run();");return;}const file=resolve(root,pathname==='/'?'index.html':'.'+pathname);let bytes=await readFile(file);if(extname(file)==='.html')bytes=Buffer.from(bytes.toString().replace('</body>','<script type="module" src="/browser-check.mjs"></script></body>'));res.setHeader('content-type',mime[extname(file)]||'application/octet-stream');res.end(bytes);}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port,child=spawn(process.env.CHROMIUM_PATH||'/usr/bin/chromium',['--headless','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--no-proxy-server','--remote-debugging-port=0',origin+path],{stdio:['ignore','ignore','pipe']});let socket;try{const endpoint=await new Promise((resolve,reject)=>{let stderr='';const timer=setTimeout(()=>reject(Error('launch timeout')),10000);child.stderr.on('data',d=>{stderr+=d.toString();const m=/DevTools listening on (ws:\/\/127\.0\.0\.1:\d+\/[^\s]+)/.exec(stderr);if(m){clearTimeout(timer);resolve(m[1]);}});});const debugOrigin=new URL(endpoint).origin.replace('ws:','http:');let page;for(let n=0;n<100;n++){const pages=await(await fetch(debugOrigin+'/json/list')).json();page=pages.find(p=>p.type==='page');if(page)break;await new Promise(r=>setTimeout(r,30));}socket=new WebSocket(page.webSocketDebuggerUrl);await new Promise((r,j)=>{socket.addEventListener('open',r,{once:true});socket.addEventListener('error',j,{once:true});});let id=0;const pending=new Map();socket.addEventListener('message',e=>{const x=JSON.parse(e.data),p=pending.get(x.id);if(p){pending.delete(x.id);p.resolve(x.result);}});const ev=expression=>new Promise(resolve=>{const n=++id;pending.set(n,{resolve});socket.send(JSON.stringify({id:n,method:'Runtime.evaluate',params:{expression,returnByValue:true}}));});let result='';for(let n=0;n<800&&!result;n++){const x=await ev("document.getElementById('browser-result')?.textContent||''");result=x.result?.value||'';await new Promise(r=>setTimeout(r,25));}assert.equal(result,'BROWSER_PASS',result||'timeout');}finally{socket?.close();child.kill('SIGKILL');server.closeAllConnections();await new Promise(r=>server.close(r));}}
test('homepage uses manual website catalogue and WhatsApp-only handoff',async()=>browserCheck({script:"document.querySelector('[data-island=Agatti]').click();document.querySelector('[data-kind=Products]').click();if(document.querySelectorAll('[data-key]').length!==1)throw Error('manual product missing');const text=new URL(document.querySelector('[data-enquiry]').href).searchParams.get('text');if(!text.includes('Product: Tuna pickle')||text.includes('NOODY_ITEM:'))throw Error('wrong handoff');if(!document.querySelector('[data-studio-home]'))throw Error('custom homepage block missing');"}));
test('manual item page shows custom section, review and WhatsApp enquiry',async()=>browserCheck({path:'/item.html?kind=PRODUCT&id=22222222-2222-4222-8222-222222222222&island=AGATTI',script:"if(document.getElementById('itemName').textContent!=='Tuna pickle')throw Error('wrong item');if(!document.getElementById('app').textContent.includes('Good product.'))throw Error('review missing');const text=new URL(document.getElementById('itemEnquiry').href).searchParams.get('text');if(!text.includes('Product: Tuna pickle')||text.includes('NOODY_ITEM:'))throw Error('core coupling found');"}));
test('full builder can add a website-only service without Core data',async()=>browserCheck({path:'/studio-builder.html',script:"document.getElementById('addService').click();if(document.getElementById('itemEditor').classList.contains('hidden'))throw Error('editor not opened');document.getElementById('name').value='My own service';document.getElementById('name').dispatchEvent(new Event('input'));const saved=JSON.parse(localStorage.getItem('noody.website.fullbuilder.v1'));if(!saved.data.items.some(i=>i.name==='My own service'))throw Error('manual item not saved');if(JSON.stringify(saved).includes('noody-ai-production.up.railway.app'))throw Error('Core API coupled');"}));
test('visual designer remains available for owner-defined website style',async()=>browserCheck({path:'/designer.html',script:"if(!document.querySelector('[data-color=accent]')||!document.getElementById('preview'))throw Error('designer missing');"}));
